import { Engine } from "../core/Engine.js";
import { ObjectSetup } from "../app/ObjectSetup.js";
import { UiSetup } from "../app/UiSetup.js";
import { ResizeSetup } from "../app/ResizeSetup.js";
import { BACKGROUND_APP_DOM as APP_MANAGER_DOM } from "../config/transition.config.js";
import { ResponsiveRuntime } from "./ResponsiveRuntime.js";
import { ShaderController } from "../controller/ShaderController.js";
import { BackgroundController } from "../controller/BackgroundController.js";
import { ShaderManager } from "../manager/ShaderManager.js";
import { ObjectFactoryRegistry } from "../core/ObjectFactoryRegistry.js";
import { UI } from "../ui/UI.js";
import type { PostProcessorOptions, RenderBudgetOptions } from "../types/engine.types.js";
import type { MainPerformanceProfile } from "../types/runtime.types.js";
import type {
  AppEngineRuntimeContext,
  AppEngineRuntimeInitOptions,
} from "../types/runtime.types.js";

export class AppEngineRuntime {
  async init(
    options: AppEngineRuntimeInitOptions,
  ): Promise<AppEngineRuntimeContext | null> {
    ResponsiveRuntime.getDefault().init();
    const canvasElement =
      options.canvasElement ??
      this._resolveCanvasElement(
        options.root,
        options.pageConfig.three?.canvasId,
      );
    const engine = this._createEngine(
      options.pageConfig,
      canvasElement,
      options.root ?? null,
    );
    if (!engine) return null;

    const shaderManager = new ShaderManager();
    shaderManager.bind(engine);

    const shaderController = new ShaderController();
    shaderController.bind(engine, shaderManager);

    const backgroundController = new BackgroundController();
    backgroundController.bind(engine);

    const objectSetup = new ObjectSetup();
    ObjectFactoryRegistry.registerPageFactories(
      objectSetup,
      options.pageConfig.pageId,
    );

    const uiSetup = new UiSetup();
    const resizeSetup = new ResizeSetup();

    return {
      engine,
      shaderManager,
      shaderController,
      backgroundController,
      objectSetup,
      uiSetup,
      resizeSetup,
    };
  }

  dispose(context: AppEngineRuntimeContext | null): void {
    if (!context) return;
    context.resizeSetup.dispose();
    context.uiSetup.dispose();
    UI.clearAll();
    context.objectSetup.dispose();
    context.shaderController.dispose();
    context.backgroundController.dispose();
    context.shaderManager.dispose();
    context.engine.dispose();
  }

  private _createEngine(
    pageConfig: AppEngineRuntimeInitOptions["pageConfig"],
    canvasElement: HTMLCanvasElement | null,
    root: ParentNode | null,
  ): Engine | null {
    const three = pageConfig.three;
    if (!three) return null;
    const responsive = ResponsiveRuntime.getDefault().getSnapshot();

    const engine = new Engine({
      canvasId: three.canvasId,
      canvasElement,
      camera: three.camera,
      cameraTarget: three.cameraTarget,
      renderer: {
        ...three.renderer,
        antialias: responsive.performance.rendererAntialias,
        powerPreference: responsive.performance.rendererPowerPreference,
      },
      pixelRatioMax: Math.min(
        three.pixelRatioMax,
        responsive.render.pixelRatioMax,
      ),
      shadowMap: three.shadowMap,
      renderBudget: this._resolveRenderBudget(
        three.renderBudget,
        responsive.performance,
      ),
      scene: three.scene,
      postProcessing: this._resolvePostProcessing(
        three.postProcessing,
        responsive.performance,
      ),
    });

    if (!engine.init()) {
      this._applyDomRendererFallback(canvasElement, root, three.canvasId);
      return null;
    }

    engine.applyResponsiveSnapshot(responsive);
    return engine;
  }

  private _resolveCanvasElement(
    root: ParentNode | null | undefined,
    canvasId: string | undefined,
  ): HTMLCanvasElement | null {
    if (!canvasId) return null;
    if (!root) {
      return document.getElementById(canvasId) as HTMLCanvasElement | null;
    }
    if (root instanceof HTMLCanvasElement && root.id === canvasId) {
      return root;
    }
    return root.querySelector<HTMLCanvasElement>(`#${canvasId}`);
  }

  private _applyDomRendererFallback(
    canvasElement: HTMLCanvasElement | null,
    root: ParentNode | null,
    canvasId: string | undefined,
  ): void {
    if (typeof document === "undefined") return;
    const target = this._resolveFallbackTarget(canvasElement, root, canvasId);
    if (!(target instanceof HTMLElement)) return;
    target.style.background = APP_MANAGER_DOM.rendererFallbackBackground;
  }

  private _resolveFallbackTarget(
    canvasElement: HTMLCanvasElement | null,
    root: ParentNode | null,
    canvasId: string | undefined,
  ): HTMLElement | null {
    if (canvasElement?.parentElement) return canvasElement.parentElement;
    if (root instanceof HTMLElement) return root;
    if (root) {
      const scopedHost = canvasId
        ? root.querySelector<HTMLElement>(`#${canvasId}`)
        : null;
      if (scopedHost) return scopedHost;
    }
    if (!canvasId) return document.body;
    const globalHost = document.getElementById(canvasId);
    if (globalHost instanceof HTMLElement) return globalHost;
    return document.body;
  }

  private _resolveRenderBudget(
    renderBudget: RenderBudgetOptions | undefined,
    performance: MainPerformanceProfile,
  ): RenderBudgetOptions | undefined {
    if (!renderBudget) return undefined;
    if (performance.tier !== "low") return renderBudget;
    return {
      ...renderBudget,
      mode: "performance",
    };
  }

  private _resolvePostProcessing(
    postProcessing: PostProcessorOptions | undefined,
    performance: MainPerformanceProfile,
  ): PostProcessorOptions | undefined {
    if (!postProcessing) return undefined;
    if (postProcessing.bloom === false) return postProcessing;

    const bloom =
      typeof postProcessing.bloom === "object" && postProcessing.bloom != null
        ? { ...performance.bloom, ...postProcessing.bloom }
        : { ...performance.bloom };

    return {
      ...postProcessing,
      bloom,
    };
  }
}

