6	} from "../../config/timeline.config.js";
7	
8	const LENIS_PREVENT_SELECTORS = [
9	  "[data-lenis-prevent]",
10	  "[data-lenis-prevent-wheel]",
11	  "[data-lenis-prevent-touch]",
12	].join(", ");
13	
14	export class LenisRuntime {
15	  private instance: LenisInstance | null = null;
16	  private rafId: number | null = null;
17	  private nativeScrollRafId: number | null = null;
18	  private lastScrollY = 0;
19	  private settleFramesLeft = 0;
20	  private isScrollbarDragSyncEnabled = false;
21	  private _initialized = false;
22	  private _disposed = false;
23	  private readonly _onPointerDown = (event: PointerEvent): void => {
24	    this.isScrollbarDragSyncEnabled = this.isScrollbarPointerDown(event);
25	  };
26	  private readonly _onPointerUp = (): void => {
27	    this.isScrollbarDragSyncEnabled = false;
28	  };
29	  private readonly _onNativeScroll = (): void => {
30	    if (!this.instance) return;
31	    if (!this.isScrollbarDragSyncEnabled) return;
32	    if (this.nativeScrollRafId != null) return;
33	    this.nativeScrollRafId = window.requestAnimationFrame(() => {
34	      this.nativeScrollRafId = null;
35	      const currentScrollY = window.scrollY ?? window.pageYOffset ?? 0;
36	      const lenisScroll =
37	        this.instance?.actualScroll ??
38	        this.instance?.animatedScroll ??
39	        currentScrollY;
40	      if (
41	        Math.abs(currentScrollY - lenisScroll) <
42	        LENIS_SCROLL_TRIGGER_SYNC_CONFIG.minDeltaPx
43	      ) {
44	        return;
45	      }
46	      this.instance?.scrollTo?.(currentScrollY, { immediate: true });
47	      this.lastScrollY = currentScrollY;
48	      this.settleFramesLeft = LENIS_SCROLL_TRIGGER_SYNC_CONFIG.settleFrames;
49	      window.ScrollTrigger?.update?.();
50	    });
51	  };
52	
53	  async init(): Promise<void> {
54	    if (this._initialized || this._disposed) return;
55	    this.onInit();
56	    this._initialized = true;
57	  }
58	
59	  dispose(): void {
60	    if (this._disposed) return;
61	    this._disposed = true;
62	    this._initialized = false;
63	    this.onDispose();
64	  }
65	
66	  private onInit(): void {
67	    if (this.instance) return;
68	
69	    const LenisCtor = this.resolveLenisCtor();
70	    if (!LenisCtor) return;
71	
72	    this.instance = new LenisCtor({
73	      autoRaf: false,
74	      smoothWheel: true,
75	      lerp: LENIS_SCROLL_CONFIG.lerp,
76	      wheelMultiplier: LENIS_SCROLL_CONFIG.wheelMultiplier,
77	      touchMultiplier: LENIS_SCROLL_CONFIG.touchMultiplier,
78	      prevent: (node: Element) => this.shouldPreventLenis(node),
79	    });
80	    (window as WindowWithLenis).__appLenis = this.instance;
81	    this.lastScrollY = window.scrollY ?? window.pageYOffset ?? 0;
82	    this.settleFramesLeft = LENIS_SCROLL_TRIGGER_SYNC_CONFIG.settleFrames;
83	
84	    const onRaf = (time: number): void => {
85	      this.instance?.raf(time);
86	      this._syncScrollTrigger();
87	      this.rafId = FrameScheduler.request(onRaf);
88	    };
89	    this.rafId = FrameScheduler.request(onRaf);
90	    window.addEventListener("scroll", this._onNativeScroll, { passive: true });
91	    window.addEventListener("pointerdown", this._onPointerDown, {
92	      passive: true,
93	    });
94	    window.addEventListener("pointerup", this._onPointerUp, {
95	      passive: true,
96	    });
97	    window.addEventListener("pointercancel", this._onPointerUp, {
98	      passive: true,
99	    });
100	  }
101	
102	  private onDispose(): void {
103	    if (this.rafId !== null) {
104	      FrameScheduler.cancel(this.rafId);
105	      this.rafId = null;
106	    }
107	    if (this.nativeScrollRafId !== null) {
108	      window.cancelAnimationFrame(this.nativeScrollRafId);
109	      this.nativeScrollRafId = null;
110	    }
111	    window.removeEventListener("scroll", this._onNativeScroll);
112	    window.removeEventListener("pointerdown", this._onPointerDown);
113	    window.removeEventListener("pointerup", this._onPointerUp);
114	    window.removeEventListener("pointercancel", this._onPointerUp);
115	    this.instance?.destroy?.();
116	    this.instance = null;
117	    this.settleFramesLeft = 0;
118	    this.isScrollbarDragSyncEnabled = false;
119	    delete (window as WindowWithLenis).__appLenis;
120	  }
121	
122	  private _syncScrollTrigger(): void {
123	    const currentScrollY = window.scrollY ?? window.pageYOffset ?? 0;
124	    const moved =
125	      Math.abs(currentScrollY - this.lastScrollY) >=
126	      LENIS_SCROLL_TRIGGER_SYNC_CONFIG.minDeltaPx;
127	    if (moved) {
128	      this.lastScrollY = currentScrollY;
129	      this.settleFramesLeft = LENIS_SCROLL_TRIGGER_SYNC_CONFIG.settleFrames;
